PREFIX li: <https://example.org/ontology/insurance#>
PREFIX abox: <https://example.org/ontology/insurance/abox#>
SELECT DISTINCT ?contractID ?evidenceType ?sourceSection ?sourceText WHERE {
  ?evidence li:sourceContractID ?contractID ; a ?evidenceType .
  VALUES ?evidenceType { li:BorrowingRestriction }
  OPTIONAL { ?evidence li:sourceContractSection ?sourceSection . }
  OPTIONAL { ?evidence li:labelValue ?sourceText . }
  FILTER(REGEX(LCASE(CONCAT(STR(?sourceSection), ' ', STR(?sourceText))), "variable universal"))
}
ORDER BY ?contractID
